const raw = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
function extractJson(text){
  if (text && typeof text === 'object') return text;
  let s = String(text).replace(/```json/gi,'```').replace(/```/g,'').trim();
  try { return JSON.parse(s); } catch(e){}
  let best=null;
  for (let i=0;i<s.length;i++){ if (s[i] !== '{') continue; let depth=0;
    for (let j=i;j<s.length;j++){ if (s[j]==='{') depth++; else if (s[j]==='}'){ depth--; if(depth===0){
      try { const o=JSON.parse(s.slice(i,j+1)); if(o && (o.metrics||o.completedSummary||o.stage||o.nextStep)) best=o; } catch(e){} break; }}}}
  return best;
}
let data = extractJson(raw);
if (!data) data = { stage:'security', stageLabel:'Keep going', metrics:{income:100,expense:50,liabilities:40,passive:0,savings:10}, completedSummary:String(raw).slice(0,400)||'Reflection unavailable.', advanced:false, nextStep:'Review your spending and pick one improvement.', highlights:['savings'] };
data.highlights = Array.isArray(data.highlights)?data.highlights:['savings'];

// override metrics with DETERMINISTIC figures (% of total income) so the reflection is grounded
const bc = $('Build Context').first().json;
const comp = bc._computed || {}; const ti = bc._totalIncome || 0;
const pctI = x => ti > 0 ? Math.round((Number(x)||0) / ti * 100) : 0;
data.metrics = Object.assign({}, data.metrics, {
  income: 100, active: pctI(comp.activeIncome), payroll: pctI(comp.payroll), training: pctI(comp.training),
  passive: pctI(comp.passiveIncome), expense: pctI(comp.expenses),
  liabilities: pctI(comp.liabilities), savings: pctI(comp.savings) });

const ev = $('Evaluate').first().json;
let progressStatement = '';
try {
  const pr = $('Get Progress').first().json;
  const t = pr && pr.result ? JSON.parse(pr.result.content[0].text) : null;
  const ps = t && (t.data ? t.data.getProgress : t.getProgress);
  if (ps && ps.progressStatement) progressStatement = ps.progressStatement;
} catch(e) {}
return [{ json: { ...data, _completion: ev.completion, _date: ev.date, _period: ev.period,
  _progressStatement: progressStatement, _trajectory: bc._trajectory || [],
  _usd: { active: comp.activeIncome, payroll: comp.payroll, training: comp.training,
          passive: comp.passiveIncome, savings: comp.savings } } }];

function trajectorySVG(tj){
  const esc = (s)=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const usd = (x)=>'$'+Math.round(Number(x)||0).toLocaleString('en-US');
  const W=720,H=340,PL=54,PR=18,PT=24,PB=46;
  const series = [ {k:'savings',name:'Savings',color:'#34d399'},
    {k:'training',name:'Training',color:'#f59e0b'}, {k:'passive',name:'Passive',color:'#a78bfa'} ];
  const n = tj.length; let maxV = 1;
  for (const p of tj){ for (const s of series) maxV=Math.max(maxV, Number(p[s.k])||0);
    maxV=Math.max(maxV, Number(p.trainingTarget)||0, Number(p.savingsTarget)||0, Number(p.passiveTarget)||0); }
  maxV = maxV*1.15;
  const xAt = i => PL + (n<=1 ? (W-PL-PR)/2 : (i*(W-PL-PR)/(n-1)));
  const yAt = v => PT + (H-PT-PB) * (1 - (Number(v)||0)/maxV);
  const path = key => tj.map((p,i)=>(i?'L':'M')+xAt(i).toFixed(1)+','+yAt(p[key]).toFixed(1)).join(' ');
  const dots = (key,color)=> tj.map((p,i)=>'<circle cx="'+xAt(i).toFixed(1)+'" cy="'+yAt(p[key]).toFixed(1)+'" r="3.5" fill="'+color+'"/>').join('');
  let grid=''; const GN=4;
  for (let g=0;g<=GN;g++){ const v=maxV*g/GN, y=yAt(v);
    grid += '<line x1="'+PL+'" y1="'+y.toFixed(1)+'" x2="'+(W-PR)+'" y2="'+y.toFixed(1)+'" stroke="#334155" stroke-width="1"/>'+
            '<text x="'+(PL-8)+'" y="'+(y+4).toFixed(1)+'" fill="#64748b" font-size="11" text-anchor="end">'+usd(v)+'</text>'; }
  const xlabels = tj.map((p,i)=>'<text x="'+xAt(i).toFixed(1)+'" y="'+(H-PB+20)+'" fill="#94a3b8" font-size="12" text-anchor="middle">'+esc(p.monthLabel)+'</text>').join('');
  const lines = series.map(s=>'<path d="'+path(s.k)+'" fill="none" stroke="'+s.color+'" stroke-width="2.5"/>'+dots(s.k,s.color)).join('');
  const tgt = (key,color)=> tj.length? '<path d="'+path(key)+'" fill="none" stroke="'+color+'" stroke-width="1.6" stroke-dasharray="5 4" opacity="0.8"/>':'';
  // dashed targets in matching colours: savings, training, and passive (passive target = essentials = security stage)
  const targets = tgt('savingsTarget','#34d399') + tgt('trainingTarget','#f59e0b') + tgt('passiveTarget','#a78bfa');
  const legend = series.map((s,i)=>'<g transform="translate('+(PL+i*128)+','+(PT-6)+')"><rect width="12" height="12" rx="2" fill="'+s.color+'"/><text x="18" y="11" fill="#cbd5e1" font-size="12">'+s.name+'</text></g>').join('');
  return '<svg viewBox="0 0 '+W+' '+H+'" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Savings and earnings trajectory">'+grid+targets+lines+xlabels+'<g>'+legend+'</g><text x="'+(W-PR)+'" y="'+(PT-6)+'" fill="#64748b" font-size="10" text-anchor="end">dashed = target (passive target = security)</text></svg>';
}
function trajectoryCards(tj){
  const esc = (s)=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const usd = (x)=>'$'+Math.round(Number(x)||0).toLocaleString('en-US');
  const a = tj[tj.length-2]||{}, b = tj[tj.length-1]||{};
  const card = (name,key,color,fmt)=>{ const cur=Number(b[key])||0, prev=Number(a[key])||0, dv=cur-prev;
    const dir = dv>0?'▲':(dv<0?'▼':'—'), dcol = dv>0?'#34d399':(dv<0?'#f87171':'#94a3b8');
    return '<div class="card mini"><div class="mlabel">'+name+'</div><div class="mval" style="color:'+color+'">'+fmt(cur)+'</div><div class="mdelta" style="color:'+dcol+'">'+dir+' '+fmt(Math.abs(dv))+' vs '+esc(a.monthLabel||'prev')+'</div></div>'; };
  return [ card('Savings','savings','#34d399',usd),
    card('Training','training','#f59e0b',usd), card('Passive','passive','#a78bfa',usd),
    card('Savings rate','savingsRate','#e2e8f0',(x)=>Math.round(x)+'%') ].join('');
}

const d = $('Parse Agent').first().json;
const m = d.metrics || {};
const comp = d._completion || {total:0,done:0,pct:0,completed:[],incomplete:[]};
const date = d._date; const period = d._period;
const stage = String(d.stage||'security').toLowerCase();
const enc = encodeURIComponent;
const clamp = (x)=>Math.max(0,Math.min(100,Math.round(Number(x)||0)));
const inc = clamp(m.income!=null?m.income:100), exp = clamp(m.expense), lia = clamp(m.liabilities);
const hl = (Array.isArray(d.highlights)&&d.highlights.length?d.highlights:['savings']).join(',');
const iframe = `https://calculator.familywealth.in/embed.html?stage=${enc(stage)}&income=${inc}&expense=${exp}&liabilities=${lia}&highlights=${enc(hl)}`;
const esc = (s)=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const tj = d._trajectory || [];
const trajCard = tj.length ? `<div class="card"><h2>Financial Security Trajectory</h2>${trajectorySVG(tj)}<div class="cards" style="margin-top:12px">${trajectoryCards(tj)}</div></div>` : '';
let progressLine = '';
if (d._progressStatement) progressLine = `<div class="card"><h2>This Week</h2><p>${esc(d._progressStatement)}</p></div>`;
const li = (arr,cls)=> (arr||[]).map(b=>`<li class="${cls}">${esc(b)}</li>`).join('');
const label = esc(d.stageLabel || stage);
const adv = d.advanced ? `<span class="badge" style="background:#16a34a">Stage advanced!</span>` : '';
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CFO Reflection</title>
<style>body{margin:0;background:#0f172a;color:#e2e8f0;font-family:system-ui,-apple-system,sans-serif;padding:24px}
.wrap{max-width:780px;margin:0 auto}.card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:20px;margin-bottom:16px}
h1,h2{color:#6366f1;margin:.2em 0}h2{color:#93c5fd;font-size:1rem}.badge{display:inline-block;background:#6366f1;color:#fff;border-radius:999px;padding:4px 14px;font-weight:600;text-transform:capitalize;margin-left:8px}
iframe{display:block;width:100%;height:420px;border:0;background:transparent}
.bar{height:14px;border-radius:999px;background:#334155;overflow:hidden;margin:10px 0}.bar>div{height:100%;background:#16a34a}
ul{padding-left:20px}li{margin:6px 0}li.done{color:#86efac}li.todo{color:#94a3b8;text-decoration:line-through}
.metrics span{display:inline-block;margin-right:16px;color:#cbd5e1}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px}
.mini{padding:14px;margin:0}.mlabel{color:#94a3b8;font-size:.78rem;text-transform:uppercase;letter-spacing:.04em}
.mval{font-size:1.35rem;font-weight:700;margin:4px 0}.mdelta{font-size:.8rem}</style></head>
<body><div class="wrap">
<div class="card" style="text-align:center"><h1>Daily Reflection</h1><p><span class="badge">${label}</span>${adv}</p>
<iframe src="${iframe}" loading="lazy"></iframe>
<p class="metrics"><span>Expense ${exp}%</span><span>Liabilities ${lia}%</span><span>Savings ${clamp(m.savings)}%</span><span>Passive ${clamp(m.passive)}%</span></p></div>
${trajCard}
<div class="card"><h2>Progress: ${comp.done}/${comp.total} done (${comp.pct}%)</h2>
<div class="bar"><div style="width:${comp.pct}%"></div></div>
${comp.completed&&comp.completed.length?`<ul>${li(comp.completed,'done')}</ul>`:''}
${comp.incomplete&&comp.incomplete.length?`<h2 style="font-size:1rem;color:#94a3b8">Still open</h2><ul>${li(comp.incomplete,'todo')}</ul>`:''}</div>
<div class="card"><h2>Today</h2><p>${esc(d.completedSummary)}</p></div>
<div class="card"><h2>Next Step</h2><p>${esc(d.nextStep)}</p></div>
${progressLine}
</div></body></html>`;
return [{ json: { html, date, period } }];

